import{_ as r,c as s,o as a,ah as i,j as e,a as t}from"./chunks/framework.D-P5O0CF.js";const d="/Qonnectra-docs/pr-16/images/manual/teil-a/fault.jpg",l="/Qonnectra-docs/pr-16/images/manual/teil-a/fault_damage_point.jpg",o="/Qonnectra-docs/pr-16/videos/fault_simulation.webm",h="/Qonnectra-docs/pr-16/images/manual/teil-a/fault_result.jpg",u="/Qonnectra-docs/pr-16/images/manual/teil-a/fault_result_detail.jpg",c="/Qonnectra-docs/pr-16/images/manual/teil-a/fault_addresses.jpg",b="/Qonnectra-docs/pr-16/images/manual/teil-a/fault_export.jpg",_=JSON.parse('{"title":"6. Störungsanalyse","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/06-stoerungsanalyse.md","filePath":"manual/teil-a-anwenderhandbuch/06-stoerungsanalyse.md"}'),g={name:"manual/teil-a-anwenderhandbuch/06-stoerungsanalyse.md"};function m(p,n,f,k,S,z){return a(),s("div",null,[...n[0]||(n[0]=[i('<h1 id="_6-storungsanalyse" tabindex="-1">6. Störungsanalyse <a class="header-anchor" href="#_6-storungsanalyse" aria-label="Permalink to &quot;6. Störungsanalyse&quot;">​</a></h1><p>Die <strong>Störungsanalyse</strong> beantwortet die Frage, was ausfällt, wenn an einer bestimmten Stelle des Netzes ein Schaden entsteht – etwa wenn bei Bauarbeiten ein Bagger eine Trasse aufreißt. Sie erreichen sie über die linke Navigationsleiste in der Gruppe „Funktionen“ durch Klicken auf den Menüpunkt „Störungsanalyse“.</p><p><img src="'+d+'" alt="Screenshot Störungsanalyse mit der Karte und dem Hinweis zum Setzen eines Schadenspunkts am unteren Rand" data-zoomable="true"></p><p>Die Simulation rechnet den Schaden nur durch. Sie ändert nichts am Datenbestand: Weder werden Kabel als gestört markiert noch Fasern abgeschaltet, und das Ergebnis wird nirgends gespeichert.</p><p>Die Karte verhält sich wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> beschrieben.</p><h2 id="_6-1-schadenspunkt-in-der-karte-setzen" tabindex="-1">6.1 Schadenspunkt in der Karte setzen <a class="header-anchor" href="#_6-1-schadenspunkt-in-der-karte-setzen" aria-label="Permalink to &quot;6.1 Schadenspunkt in der Karte setzen&quot;">​</a></h2><p>Solange kein Schadenspunkt gesetzt ist, steht am unteren Rand der Karte der Hinweis „Klicken Sie auf einen Graben in der Karte, um einen Schadenspunkt zu setzen“. Gemeint ist damit ein Trassensegment, also ein Objekt des Layers „Trasse“.</p><p>Klicken Sie auf die Trasse, an der der Schaden liegt. Sie müssen die Linie nicht genau treffen – ein Klick in ihre Nähe genügt, Qonnectra setzt den Punkt auf die nächstgelegene Stelle der Linie. Anklickbar sind ausschließlich Trassensegmente; Adressen, Netzknoten und Gebiete zeichnet die Karte zwar mit, ein Klick auf sie bleibt hier aber wirkungslos.</p><p>Über dem gesetzten Punkt erscheint ein kleines Fenster mit der Trassen-ID, der Bauart und dem Button „Simulation starten“.</p><p><img src="'+l+'" alt="Screenshot Störungsanalyse mit Hervorhebung des gesetzten Schadenspunkts und des Fensters „Simulation starten“ in der Kartenmitte" data-zoomable="true"></p><p>Ein Klick auf eine andere Trasse verschiebt den Schadenspunkt dorthin, solange die Simulation noch nicht gelaufen ist.</p>',11),e("p",null,[e("video",{src:o,controls:"",playsinline:"",preload:"metadata"},[t(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/fault_simulation.webm",download:""},"herunterladen"),t(" anstelle des Videos. ")])],-1),i('<div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>An einer Verzweigung kann die Trasse, mit der die Simulation rechnet, von der im Fenster genannten abweichen: Das Fenster nennt die angeklickte Trasse, die Auswertung sucht anschließend erneut die Trasse, die dem gesetzten Punkt am nächsten liegt. Laufen dort zwei Trassen zusammen, ist das nicht zwingend dieselbe. Welche es war, steht in der Kopfzeile des Ergebnisses. Setzen Sie den Punkt deshalb in der Mitte einer Trasse und nicht an ihrem Ende.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Sobald ein Ergebnis angezeigt wird, nimmt die Karte keine Klicks mehr an. Um einen anderen Schadenspunkt zu untersuchen, verwerfen Sie das Ergebnis zuerst über „Zurücksetzen“, siehe Abschnitt <a href="#_6-4-ergebnis-als-csv-exportieren">Ergebnis als CSV exportieren</a>.</p></div><h2 id="_6-2-betroffene-leerrohre-kabel-und-fasern" tabindex="-1">6.2 Betroffene Leerrohre, Kabel und Fasern <a class="header-anchor" href="#_6-2-betroffene-leerrohre-kabel-und-fasern" aria-label="Permalink to &quot;6.2 Betroffene Leerrohre, Kabel und Fasern&quot;">​</a></h2><p>Mit „Simulation starten“ teilt sich die Ansicht: Oben bleibt die Karte, unten erscheint das Ergebnis. In dessen Kopfzeile stehen die Trassen-ID und die Bauart der getroffenen Trasse, daneben die Buttons „CSV exportieren“ und „Zurücksetzen“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Auswertung verfolgt jede einzelne Faser jedes betroffenen Kabels und braucht dafür je nach Umfang des Netzes einige Sekunden bis zu einer Minute. Solange dreht sich ein Ladezeichen im Button; warten Sie es ab, ein zweiter Klick beschleunigt nichts. Scheitert die Auswertung, erscheint am unteren Bildschirmrand die Meldung „Fehler bei der Simulation“ und die Ansicht bleibt unverändert.</p></div><p>Darunter liegen zwei Listen, die beim Öffnen des Ergebnisses <strong>zugeklappt</strong> sind; ein Klick auf ihre Überschrift klappt sie auf und wieder zu. Hinter der Überschrift steht in Klammern die Anzahl der Einträge, die Sie also auch ohne Aufklappen ablesen können:</p><ul><li>„Betroffene Leerrohre“ – die Rohre, die der getroffenen Trasse zugeordnet sind, mit ihrem Rohrtyp.</li><li>„Betroffene Kabel“ – die Kabel, die durch diese Rohre laufen, mit Kabeltyp sowie Start- und Endknoten. Führt die Trasse kein Kabel, steht dort „Keine Kabel in dieser Trasse“.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ist der Trasse kein Rohr zugeordnet, fehlt die Überschrift „Betroffene Leerrohre“ vollständig – anders als bei den Kabeln gibt es hier keine Meldung, die den Leerzustand benennt. Das Ergebnis beginnt dann unmittelbar mit den Kabeln oder ist ganz leer. Prüfen Sie in diesem Fall die Rohrzuordnung der Trasse, siehe Kapitel <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>.</p></div><p>Die untere Hälfte ist ein eigener Scrollbereich. Sind beide Listen aufgeklappt, liegt die Adressliste aus Abschnitt <a href="#_6-3-betroffene-adressen-und-wohneinheiten">Betroffene Adressen und Wohneinheiten</a> unterhalb des sichtbaren Bereichs; scrollen Sie dann im Ergebnis nach unten.</p><p>Die Karte zeigt denselben Sachverhalt räumlich: den Schadenspunkt, die Trassen, in denen die betroffenen Kabel verlaufen, sowie die Netzknoten und Adressen, die dadurch ohne Signal wären.</p><p class="img-row"><img src="'+h+'" alt="Screenshot Störungsanalyse mit dem Ergebnis: Karte in der oberen Hälfte, darunter die aufgeklappten Listen „Betroffene Leerrohre“ und „Betroffene Kabel“" data-zoomable="true"><img src="'+u+'" alt="Ausschnitt der Karte mit dem Schadenspunkt und den hervorgehobenen Trassen der betroffenen Kabel" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Analyse rechnet mit der gesamten Trasse, nicht mit dem angeklickten Punkt. Betroffen ist alles, was der Trasse zugeordnet ist – jedes Rohr und jedes Kabel darin, unabhängig davon, an welcher Stelle Sie geklickt haben. Ein Schaden am Anfang und einer am Ende desselben Trassensegments liefern dasselbe Ergebnis.</p></div><p>Die Fasern zählt Qonnectra ebenfalls mit: Jede Faser eines betroffenen Kabels gilt als durchtrennt. Auf dem Bildschirm erscheinen diese Zahlen nicht; Faserzahlen stehen ausschließlich in der CSV-Datei, siehe Abschnitt <a href="#_6-4-ergebnis-als-csv-exportieren">Ergebnis als CSV exportieren</a>.</p><h2 id="_6-3-betroffene-adressen-und-wohneinheiten" tabindex="-1">6.3 Betroffene Adressen und Wohneinheiten <a class="header-anchor" href="#_6-3-betroffene-adressen-und-wohneinheiten" aria-label="Permalink to &quot;6.3 Betroffene Adressen und Wohneinheiten&quot;">​</a></h2><p>Unter den beiden Listen steht „Betroffene Adressen“, ebenfalls mit der Anzahl in Klammern. Anders als die beiden Listen darüber lässt sich diese Aufstellung nicht zuklappen. Sie ist eine Tabelle mit den Spalten „Adress-ID“, „Straße“, „Ort“ und „Wohneinheiten“; „Straße“ enthält die Hausnummer mit, „Ort“ die Postleitzahl, und „Wohneinheiten“ nennt deren Anzahl je Adresse.</p><p>Unter jeder Adresse sind ihre betroffenen Wohneinheiten eingerückt aufgeführt, je Wohneinheit die Wohneinheit-ID, Etage und Seite, der Typ und der Status. Fehlt einer Wohneinheit eine dieser Angaben, bleibt die Stelle leer. Adress-ID und Wohneinheit-ID sind verlinkt und führen in die zugehörige Adresse, siehe Kapitel <a href="./16-adressen.html">Adressen</a>.</p><p><img src="'+c+'" alt="Screenshot Störungsanalyse mit Hervorhebung der Tabelle „Betroffene Adressen“ mit ihren eingerückten Wohneinheiten in der unteren Hälfte" data-zoomable="true"></p><p>Woher diese Liste kommt, ist für die Praxis wichtig: Qonnectra verfolgt jede Faser der betroffenen Kabel über ihre Spleiße weiter – so, wie es der Faserweg tut, siehe Kapitel <a href="./15-faserweg.html">Faserweg</a>. Erst die Netzknoten, die auf diesem Weg erreicht werden, liefern die Adressen und Wohneinheiten.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Sind die Fasern eines Kabels nirgends gespleißt, endet die Verfolgung beim Kabel selbst. Anstelle der Tabelle meldet die Störungsanalyse dann „Keine betroffenen Adressen“ – auch dann, wenn das Kabel an einem Hausanschluss endet. Die Meldung heißt also nicht zwingend „niemand ist betroffen“, sondern kann auch bedeuten, dass die Spleiße noch nicht dokumentiert sind.</p></div><h2 id="_6-4-ergebnis-als-csv-exportieren" tabindex="-1">6.4 Ergebnis als CSV exportieren <a class="header-anchor" href="#_6-4-ergebnis-als-csv-exportieren" aria-label="Permalink to &quot;6.4 Ergebnis als CSV exportieren&quot;">​</a></h2><p>„CSV exportieren“ lädt das Ergebnis als Datei <code>fault-simulation-&lt;Trassen-ID&gt;.csv</code> herunter; Trassen-IDs über 20 Zeichen werden im Dateinamen gekürzt. Die Datei enthält vier Abschnitte:</p><ul><li>die getroffene Trasse mit Trassen-ID und Bauart,</li><li>die betroffenen Leerrohre mit Name und Rohrtyp,</li><li>die betroffenen Kabel mit Name, Kabeltyp, „Fiber Count“, „Dark Fibers“ sowie Start- und Endknoten,</li><li>die betroffenen Adressen, eine Zeile je Wohneinheit.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>„Fiber Count“ ist die Faseranzahl des Kabels, „Dark Fibers“ ist <strong>nicht</strong> deren gestörter Anteil. Die Spalte zählt jedes Fasersegment, das Qonnectra beim Verfolgen der Kabelfasern ohne Signal findet – also auch die Fasern der nachgelagerten Kabel jenseits der Spleiße. Der Wert kann dadurch größer sein als „Fiber Count“. Als Antwort auf „Wie viele Fasern dieses Kabels sind durchtrennt?“ ist er falsch gelesen: Durchtrennt sind immer alle.</p></div><p><img src="'+b+'" alt="Screenshot Störungsanalyse mit Hervorhebung der Buttons „CSV exportieren“ und „Zurücksetzen“ in der Kopfzeile des Ergebnisses" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Abschnitts- und Spaltenüberschriften der Datei sind englisch, unabhängig von der eingestellten Sprache. Zu den Exportformaten insgesamt siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-8-exportformate-im-uberblick">Exportformate im Überblick</a>.</p></div><p>„Zurücksetzen“ verwirft das Ergebnis. Die Karte nimmt danach wieder die volle Höhe ein und ist bereit für den nächsten Schadenspunkt.</p><h2 id="_6-5-was-die-simulation-nicht-abbildet" tabindex="-1">6.5 Was die Simulation nicht abbildet <a class="header-anchor" href="#_6-5-was-die-simulation-nicht-abbildet" aria-label="Permalink to &quot;6.5 Was die Simulation nicht abbildet&quot;">​</a></h2><p>Die Störungsanalyse ist eine Auswertung des dokumentierten Netzes, keine Prognose. Sie sollten die Grenzen kennen, bevor Sie das Ergebnis weitergeben:</p><ul><li><strong>Die Trasse ist die kleinste Einheit.</strong> Der Schadenspunkt dient der Auswahl der Trasse, nicht der Berechnung. Ein Schaden, der nur ein einzelnes Rohr im Graben trifft, lässt sich nicht abbilden, siehe Abschnitt <a href="#_6-2-betroffene-leerrohre-kabel-und-fasern">Betroffene Leerrohre, Kabel und Fasern</a>.</li><li><strong>Es gibt keine Ersatzwege.</strong> Jede Faser eines betroffenen Kabels gilt als durchtrennt. Ob ein Signal über eine andere Strecke geführt werden könnte, prüft Qonnectra nicht.</li><li><strong>Das Ergebnis hängt an drei Zuordnungen.</strong> Die Simulation liest nur, was dokumentiert ist, und sie liest es in dieser Kette: Rohre findet sie über die Rohrzuordnung der Trasse (siehe Kapitel <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>), Kabel über die Verknüpfung von Mikrorohr und Kabel (siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>), Adressen über die Spleiße (siehe Abschnitt <a href="#_6-3-betroffene-adressen-und-wohneinheiten">Betroffene Adressen und Wohneinheiten</a>). Fehlt ein Glied, endet die Auswertung dort – ohne Hinweis darauf, dass sie es getan hat.</li><li><strong>Immer nur ein Schadenspunkt.</strong> Mehrere gleichzeitige Schäden lassen sich nicht zusammen untersuchen.</li><li><strong>Kein Ergebnisspeicher.</strong> Die Simulation wird nirgends abgelegt. Sobald Sie den Menüpunkt verlassen, ist sie verloren; halten Sie das Ergebnis über den CSV-Export fest.</li></ul><p>Die Störungsanalyse sagt außerdem nichts über Dauer, Aufwand oder Kosten einer Reparatur aus.</p>',30)])])}const K=r(g,[["render",m]]);export{_ as __pageData,K as default};
